import { RefObject, useEffect } from 'react';
import { Handler, PossibleEvent } from './useOnClickOutside.types';

export function useOnClickOutside(ref: RefObject<HTMLElement>, handler: Handler) {
  useEffect(() => {
    const listener = (event: PossibleEvent) => {
      if (!ref.current || ref.current.contains(event.target as Node)) {
        return;
      }
      if (window.TouchEvent && event instanceof TouchEvent) {
        // Browsers fire mouse events after touch events,
        // so we need to prevent the handler from being called twice
        event.preventDefault();
      }

      handler(event);
    };
    document.addEventListener('mousedown', listener);
    document.addEventListener('touchend', listener);
    return () => {
      document.removeEventListener('mousedown', listener);
      document.removeEventListener('touchend', listener);
    };
  }, [ref, handler]);
}
